import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

// Run with node .github/scripts/sync-work-homepage.mjs after editing index.html.
// GitHub Pages serves the generated copy directly from the publishing branch.
const homepage = new URL("../../index.html", import.meta.url);
const workDirectory = new URL("../../work/", import.meta.url);
const html = readFileSync(homepage, "utf8");
const cvLink = 'href="AndyZhao_cv.pdf"';

if (html.split(cvLink).length !== 2) {
  throw new Error("Expected one CV link in the homepage.");
}

const workHtml = html
  .replace(cvLink, 'href="/work/AndyZhao_cv.pdf"')
  .replace(/\b(href|src)="(?![a-z][a-z\d+.-]*:|[/#])([^"]+)"/gi, '$1="/$2"')
  .replace('<meta property="og:url" content="https://zehao.org/">',
    '<meta property="og:url" content="https://zehao.org/work/">')
  .replace("<!DOCTYPE html>", "<!DOCTYPE html>\n<!-- Generated by .github/scripts/sync-work-homepage.mjs -->");

mkdirSync(workDirectory, { recursive: true });
writeFileSync(new URL("index.html", workDirectory), workHtml);
